/* Тема «Стекло» (style-themes.js): размытие карточек за их фоном. Стандартная тема эти правила не получает. */
html.theme-glass .action-slot, html.theme-glass .hero-clock, html.theme-glass #weather-widget, html.theme-glass .player-widget, html.theme-glass .hw-card, html.theme-glass .hw-custom {
